(()=>{'use strict';const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const route=['dashboard','catalog','progress','profile'].includes(location.pathname.split('/')[1])?location.pathname.split('/')[1]:'dashboard';const defaults={displayName:'',goal:'',dailyMinutes:30};let lessons=[],state={studied:[],passed:[],solved:[],drafts:{},lang:'python',lessonId:'py01',profile:defaults},account=null,loadError='',signedOut=false,profileDirty=false;const title={dashboard:'Mission control',catalog:'Course catalog',progress:'Your progress',profile:'Learner profile'};document.title='CodeTrail — '+title[route];$('breadcrumb').textContent=title[route].toUpperCase();document.querySelectorAll('[data-route]').forEach(a=>{if(a.dataset.route===route){a.classList.add('active');a.setAttribute('aria-current','page');}});$('hub-account').href='/signin-with-chatgpt?return_to='+encodeURIComponent('/'+route);const profile=()=>({...defaults,...state.profile});const initials=()=>profile().displayName.trim().split(/\s+/).filter(Boolean).map(x=>x[0]).slice(0,2).join('').toUpperCase()||'CT';const href=(l,pi)=>'/learn?language='+l.language+'&lesson='+encodeURIComponent(l.id)+(pi===undefined?'':'&problem='+pi);const problems=l=>l.problems||[l.problem];const problemKeys=l=>problems(l).map((_,i)=>l.id+l.language+':'+i);const quizKeys=l=>problems(l).map((_,i)=>l.id+':'+i);const studied=l=>(state.studied||[]).includes(l.id);function stats(rows=lessons){const keys=rows.flatMap(problemKeys),q=rows.flatMap(quizKeys);return{studied:rows.filter(studied).length,total:rows.length,solved:keys.filter(k=>(state.solved||[]).includes(k)&&k.includes('python')).length,quizzes:q.filter(k=>(state.passed||[]).includes(k)).length,quizTotal:q.length,drafts:keys.filter(k=>Object.hasOwn(state.drafts||{},k)).length};}function current(){return lessons.find(l=>l.id===state.lessonId&&l.language===state.lang)||lessons[0];}const heading=(eye,h,sub)=>`<p class="eyebrow">${eye}</p><h1 class="page-title">${h}</h1><p class="page-subtitle">${sub}</p>`;function banner(){if(loadError)return `<div class="notice error" role="status">${esc(loadError)} <button class="button outline" id="retry-load">Retry</button></div>`;if(signedOut)return `<div class="notice">You're exploring as a guest. <a href="/signin-with-chatgpt?return_to=${encodeURIComponent('/'+route)}">Sign in</a> to load your personal progress and save your profile. Google is available in the OpenAI login flow.</div>`;return `<div class="notice">Connected to your account · Progress shown is your latest cloud-saved work. <a href="/learn">Continue in the workspace ↗</a></div>`;}function metrics(s){return `<div class="metrics"><div class="metric"><strong>${s.studied}<small> / ${s.total}</small></strong><span>LESSONS MARKED STUDIED</span></div><div class="metric"><strong>${s.solved}<small> / 96</small></strong><span>PYTHON TEST SUITES PASSED</span></div><div class="metric"><strong>${s.quizzes}<small> / ${s.quizTotal}</small></strong><span>KNOWLEDGE CHECKS PASSED</span></div><div class="metric"><strong>${s.drafts}</strong><span>SAVED EXERCISE DRAFTS</span></div></div>`;}function lessonRow(l,i){return `<a class="lesson-row" href="${href(l)}"><span class="number">${studied(l)?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${esc(l.title)}</strong><small>${esc(l.moduleTitle||l.level)} · ${l.language==='python'?'Python':'Java'}${l.durationMinutes?' · '+l.durationMinutes+' min':''}</small></div><span>↗</span></a>`;}
function dashboard(){const s=stats(),l=current(),p=profile();const next=lessons.filter(x=>x.language===(state.lang||'python')&&!studied(x)).slice(0,3);return heading('YOUR SPACE / YOUR PACE',p.displayName?'WELCOME BACK, '+esc(p.displayName)+'.':'YOUR NEXT CHAPTER.','A clear path forward. Pick up your work, explore a new idea or see how far you’ve come.')+banner()+`<section class="mission-hero"><p class="eyebrow">${account?'CONTINUE YOUR JOURNEY':'READY WHEN YOU ARE'}</p><h2>${esc(l.title)}</h2><p>${esc(l.summary)}</p><div class="button-row"><a class="button" href="${href(l)}">${account?'Continue learning':'Start learning'} ↗</a><a class="button outline" href="/catalog">Explore all lessons</a></div></section>`+metrics(s)+`<div class="two-col"><section class="panel"><h2>Your next steps</h2>${next.length?next.map(lessonRow).join(''):'<p>Every lesson is marked studied. Revisit an unfamiliar problem and explain it without notes.</p>'}<p class="muted">Suggestions follow course order, based on your studied bookmarks.</p></section><section class="panel"><p class="eyebrow">A LITTLE CONSISTENCY GOES A LONG WAY</p><h2>Your learning intention</h2><p class="goal-preview">${esc(p.goal||'Make space for one new idea today.')}</p><p>${p.dailyMinutes} minutes per day is your planning target. Study time is not automatically tracked.</p><a class="button outline" href="/profile">Personalize your profile ↗</a></section></div><div class="section-head"><h2>Built for the way you learn</h2><a href="/#questions">How it works ↗</a></div><div class="two-col"><section class="panel"><span class="tag">PRACTICE WITH PURPOSE</span><h2 style="margin-top:15px">Think. Code. Test. Explain.</h2><p>Progressive hints, worked solutions and complexity notes help you build understanding beyond a green test result.</p><a class="button outline" href="${href(l,0)}">Open a challenge ↗</a></section><section class="panel"><span class="tag">YOUR ON-DEVICE AI TUTOR</span><h2 style="margin-top:15px">A second way to see it.</h2><p>Ask for an explanation or a code review from the workspace. Requires a compatible WebGPU browser and a first-time model download.</p><a class="button outline" href="/learn">Go to the tutor ↗</a></section></div>`;}
function catalog(){return heading('THE COMPLETE LEARNING PATH','FIND YOUR NEXT IDEA.','Search across Python, Java, algorithms, lesson topics and coding exercises.')+`<form class="filters" id="catalog-filters"><label>SEARCH THE CATALOG<input id="catalog-search" type="search" placeholder="Try graphs, loops or two sum…" maxlength="150"></label><label>LANGUAGE<select id="filter-language"><option value="all">All languages</option><option value="python">Python course</option><option value="java">Java basics</option></select></label><label>MODULE<select id="filter-module"><option value="all">All modules</option></select></label><label>CHALLENGE LEVEL<select id="filter-difficulty"><option value="all">All levels</option></select></label></form><div class="result-header"><span id="result-count" role="status"></span><button id="clear-filters">Clear filters</button></div><div class="course-grid" id="catalog-results"></div>`;}
function setupCatalog(){const q=new URLSearchParams(location.search);$('catalog-search').value=(q.get('q')||'').slice(0,150);const langs=['all','python','java'];$('filter-language').value=langs.includes(q.get('language'))?q.get('language'):'all';const levels=[...new Set(lessons.flatMap(l=>problems(l).map(p=>p.difficulty||'Practice')))];$('filter-difficulty').innerHTML='<option value="all">All levels</option>'+levels.map(d=>`<option value="${esc(d)}">${esc(d)}</option>`).join('');$('filter-difficulty').value=levels.includes(q.get('difficulty'))?q.get('difficulty'):'all';function modules(){const lang=$('filter-language').value;const selected=$('filter-module').value;const values=[...new Map(lessons.filter(l=>lang==='all'||l.language===lang).map(l=>[l.language+':'+(l.moduleId||l.level),l.moduleTitle||l.level])).entries()];$('filter-module').innerHTML='<option value="all">All modules</option>'+values.map(([id,label])=>`<option value="${esc(id)}">${esc(label)}</option>`).join('');$('filter-module').value=values.some(([id])=>id===selected)?selected:'all';}modules();if([...$('filter-module').options].some(x=>x.value===q.get('module')))$('filter-module').value=q.get('module');function renderResults(){const term=$('catalog-search').value.trim().toLowerCase(),language=$('filter-language').value,module=$('filter-module').value,diff=$('filter-difficulty').value;const rows=lessons.filter(l=>{const matches=problems(l).filter(p=>diff==='all'||(p.difficulty||'Practice')===diff);const text=[l.title,l.summary,l.moduleTitle,l.lesson,...matches.map(p=>p.title+' '+(p.pattern||'')+' '+p.prompt)].join(' ').toLowerCase();return(language==='all'||l.language===language)&&(module==='all'||l.language+':'+(l.moduleId||l.level)===module)&&matches.length>0&&(!term||term.split(/\s+/).every(t=>text.includes(t)));});$('result-count').textContent=rows.length+' '+(rows.length===1?'lesson':'lessons')+' found · '+(language==='java'?'Java editor and downloads':'Written lessons with hands-on exercises');$('catalog-results').innerHTML=rows.map(l=>`<article class="course-card"><div class="card-top"><span>${l.language.toUpperCase()} / ${esc(l.moduleTitle||l.level)}</span><span>${studied(l)?'✓ STUDIED':''}</span></div><h2><a href="${href(l)}">${esc(l.title)}</a></h2><p>${esc(l.summary)}</p><div class="card-bottom"><span>${l.durationMinutes?l.durationMinutes+' MIN · ':''}${problems(l).length} ${problems(l).length===1?'EXERCISE':'EXERCISES'}</span><a href="${href(l)}" aria-label="Open ${esc(l.title)}">OPEN LESSON ↗</a></div><details><summary>Explore exercises</summary>${problems(l).map((p,i)=>(diff==='all'||(p.difficulty||'Practice')===diff)?`<a href="${href(l,i)}">${esc(p.title)} <span class="tag">${esc(p.difficulty||'Practice')}</span> ↗</a>`:'').join('')}</details></article>`).join('')||'<div class="empty">No lessons match those filters. Try a broader search or clear the filters.</div>';const params=new URLSearchParams();if(term)params.set('q',$('catalog-search').value.trim());if(language!=='all')params.set('language',language);if(module!=='all')params.set('module',module);if(diff!=='all')params.set('difficulty',diff);window.LearnerFeatures?.trackSearch?.(term);history.replaceState(null,'','/catalog'+(params.size?'?'+params.toString():''));}$('catalog-search').oninput=renderResults;$('filter-language').onchange=()=>{modules();renderResults();};$('filter-module').onchange=renderResults;$('filter-difficulty').onchange=renderResults;$('catalog-filters').onsubmit=e=>{e.preventDefault();renderResults();};$('clear-filters').onclick=()=>{$('catalog-search').value='';$('filter-language').value='all';modules();$('filter-module').value='all';$('filter-difficulty').value='all';renderResults();};renderResults();}
function progress(){return heading('EVIDENCE OF YOUR EFFORT','SMALL WINS. REAL PROGRESS.','Your saved milestones, without turning bookmarks into promises of mastery.')+banner()+metrics(stats())+`<div class="track-tabs" role="group" aria-label="Progress language"><button data-track="python" class="active" aria-pressed="true">Python course</button><button data-track="java" aria-pressed="false">Java basics</button></div><div id="track-progress"></div><div class="section-head"><h2>Return to a saved draft</h2></div><section class="panel">${lessons.flatMap(l=>problems(l).map((p,i)=>({l,p,i,key:problemKeys(l)[i]}))).filter(x=>Object.hasOwn(state.drafts||{},x.key)).slice(0,12).map(x=>`<a class="lesson-row" href="${href(x.l,x.i)}"><span class="number">{ }</span><div><strong>${esc(x.p.title)}</strong><small>${x.l.language.toUpperCase()} · ${esc(x.l.title)}</small></div><span>↗</span></a>`).join('')||'<p>No saved drafts yet. Open a challenge and write your first solution.</p>'}</section>`;}
function renderTrack(language){const rows=lessons.filter(l=>l.language===language),s=stats(rows),pct=Math.round(100*s.studied/rows.length),groups=[...new Map(rows.map(l=>[l.moduleId||l.level,l.moduleTitle||l.level])).entries()];$('track-progress').innerHTML=`<div class="two-col"><section class="panel"><h2>Module milestones</h2>${groups.map(([id,name])=>{const ls=rows.filter(l=>(l.moduleId||l.level)===id),n=ls.filter(studied).length;return `<div class="progress-item"><div class="bar-label"><span>${esc(name)}</span><span>${n} / ${ls.length}</span></div><div class="bar" role="progressbar" aria-label="${esc(name)} lessons marked studied" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${ls.length}" style="--value:${100*n/ls.length}%"><span></span></div><small>Lessons marked studied</small></div>`;}).join('')}</section><section class="panel"><h2>Your ${language==='python'?'Python':'Java'} journey</h2><div class="ring" style="--percent:${pct}%"><div><strong>${pct}%</strong><small>MARKED STUDIED</small></div></div><p>${s.studied} of ${s.total} lessons marked studied. ${s.quizzes} of ${s.quizTotal} knowledge checks passed.</p><p>${language==='python'?s.solved+' of 96 supplied Python test suites passed. Tests cover examples and edge cases, not all inputs.':'Java has an editor and downloads, but no in-browser compiler or automatic tests.'}</p><p>A studied bookmark or a passed test is a milestone. Assess readiness by solving unfamiliar problems independently and explaining why your approach works.</p><a class="button outline" href="/catalog?language=${language}">Explore this track ↗</a></section></div>`;}
function profileScreen(){const p=profile(),s=stats();return heading('YOUR LEARNER IDENTITY','MAKE THIS YOUR SPACE.','Set a name, a learning goal and a daily intention. Keep your next step in sight.')+banner()+`<div class="profile-grid"><section class="panel profile-identity"><div class="avatar" id="profile-avatar">${esc(initials())}</div><h2 id="profile-name">${esc(p.displayName||'CodeTrail learner')}</h2><p>${account?'Account connected':'Guest explorer'}</p><span class="tag">${state.lang==='java'?'JAVA BASICS':'PYTHON + DSA'}</span><div class="identity-stats"><div><strong>${s.studied}</strong><span>studied lessons</span></div><div><strong>${s.solved}</strong><span>test suites passed</span></div></div><p class="profile-note">Your profile is for your own learning space. It is not a public profile.</p></section><section class="panel"><h2>Learning preferences</h2><form class="profile-form" id="profile-form"><fieldset ${account?'':'disabled'}><label class="field">Display name<input id="display-name" maxlength="60" value="${esc(p.displayName)}" placeholder="What should we call you?" autocomplete="nickname"><small>Up to 60 characters. You can leave this blank.</small></label><label class="field">What are you working toward?<textarea id="learning-goal" maxlength="300" placeholder="For example: understand Python and explain my solutions confidently">${esc(p.goal)}</textarea><small>A personal note, not a public bio. Avoid sensitive information.</small></label><label class="field">Daily practice intention<select id="daily-minutes">${[10,15,20,30,45,60,90,120,180,240].map(m=>`<option value="${m}" ${p.dailyMinutes===m?'selected':''}>${m} minutes</option>`).join('')}</select><small>A planning target only. This does not schedule reminders or track time.</small></label><button class="button" id="save-profile" type="submit">Save profile ↗</button></fieldset><p class="form-status" id="profile-status" role="status">${account?'Changes are saved only when you choose Save profile.':'Sign in to edit and save these preferences.'}</p></form><div class="profile-note">Account access uses OpenAI sign-in. This profile does not change your OpenAI name, email or password. <a href="/#questions">Learn about saved data ↗</a></div></section></div>`;}
async function api(method='GET',body){const ctrl=new AbortController(),t=setTimeout(()=>ctrl.abort(),15000);try{const r=await fetch('/api/progress',{method,credentials:'same-origin',cache:'no-store',signal:ctrl.signal,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined});return{ok:r.ok,status:r.status,value:await r.json()};}finally{clearTimeout(t);}}
function setupProfile(){const original={...profile()};$('profile-form').oninput=()=>{profileDirty=true;$('profile-status').textContent='Unsaved changes';};$('profile-form').onsubmit=async e=>{e.preventDefault();if(!account)return;const desired={displayName:$('display-name').value.trim().slice(0,60),goal:$('learning-goal').value.trim().slice(0,300),dailyMinutes:Number($('daily-minutes').value)};const patch=Object.fromEntries(Object.entries(desired).filter(([k,v])=>v!==original[k]));if(!Object.keys(patch).length){profileDirty=false;$('profile-status').textContent='Your profile is already up to date.';return;}$('save-profile').disabled=true;$('profile-form').querySelector('fieldset').disabled=true;$('profile-status').textContent='Saving your profile…';try{let r=await api();for(let attempt=0;attempt<4;attempt++){if(!r.ok&&r.status!==409)throw Error(r.status===401?'Your session ended. Sign in again, then return to your profile.':'Could not load current account data. Your edits are still here.');if(r.value.account!==account)throw Error('The signed-in account changed. Reload before saving. Nothing was transferred.');const remote={...defaults,...r.value.state.profile};if(Object.keys(patch).some(k=>remote[k]!==original[k]&&remote[k]!==desired[k]))throw Error('This profile was edited in another tab. Copy your changes, reload, and review the latest profile before saving.');const updated={...r.value.state,profile:{...remote,...patch}};r=await api('PUT',{account,revision:r.value.revision,state:updated});if(r.ok){if(r.value.account!==account)throw Error('Account changed. Reload to check your profile.');state=r.value.state;Object.assign(original,profile());profileDirty=false;$('profile-status').textContent='Profile saved to your account';$('profile-name').textContent=profile().displayName||'CodeTrail learner';$('profile-avatar').textContent=initials();$('header-avatar').textContent=initials();return;}if(r.status!==409)throw Error(r.value.error||'Could not save. Your edits are still here; try again.');}throw Error('Your account is updating in another tab. Wait a moment, then save again.');}catch(err){$('profile-status').textContent=err.name==='AbortError'?'Connection timed out. Your edits are still here; try saving again.':err.message;}finally{$('save-profile').disabled=false;$('profile-form').querySelector('fieldset').disabled=false;}};}
async function academySummaryPanel(){const target=$('academy-account-summary');if(!target)return;try{const r=await fetch('/api/academy',{credentials:'same-origin',cache:'no-store'});if(!r.ok)return;const a=await r.json();if(a.account!==account)return;target.innerHTML='<p class="eyebrow">AI ACADEMY ACHIEVEMENTS</p><h2>'+a.summary.points+' points · '+a.summary.credits+' learning credits</h2><p>'+a.summary.coursesCompleted.length+' AI courses completed · '+a.summary.tasksCompleted+' practical tasks submitted · '+esc(a.summary.level)+' learning level</p><a class="button outline" href="/achievements">View achievements ↗</a>';}catch{}}
function render(){const screens={dashboard,catalog,progress,profile:profileScreen};$('hub-content').innerHTML=screens[route]();if(['dashboard','progress','profile'].includes(route)){$('hub-content').insertAdjacentHTML('beforeend','<section class="panel" id="academy-account-summary" style="margin-top:25px"><p class="eyebrow">GO FURTHER WITH AI</p><h2>From AI foundations to agentic systems</h2><p>Detailed courses, practical tasks, checkpoints and internal learning credits.</p><a class="button" href="/academy">Explore AI academy ↗</a> <a class="button outline" href="/tasks">Your tasks ↗</a></section>');if(account)academySummaryPanel();}if(route==='catalog')$('hub-content').insertAdjacentHTML('afterbegin','<div class="notice">Looking for AI, machine learning, RAG or agentic systems? <a href="/academy">Explore the AI academy ↗</a></div>');$('header-avatar').textContent=initials();if(account){$('hub-account').textContent='Sign out ↗';$('hub-account').href='/signout-with-chatgpt?return_to='+encodeURIComponent('/'+route);}if($('retry-load'))$('retry-load').onclick=()=>location.reload();if(route==='catalog')setupCatalog();if(route==='progress'){renderTrack('python');document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-track]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderTrack(b.dataset.track);});}if(route==='profile'){setupProfile();$('hub-content').insertAdjacentHTML('beforeend','<section id="learner-settings"></section>');window.LearnerFeatures?.renderProfile($('learner-settings'));}if(route==='dashboard'){$('hub-content').insertAdjacentHTML('beforeend','<section class="panel recommendation-panel" id="learner-recommendations"></section>');window.LearnerFeatures?.suggestions($('learner-recommendations'));}window.LearnerFeatures?.updateAvatars();}
async function start(){try{const [p,j]=await Promise.all(['/course-python.json','/curriculum.json'].map(async u=>{const r=await fetch(u);if(!r.ok)throw Error('Course unavailable');return r.json();}));lessons=[...p.map(x=>({...x,language:'python'})),...j.map(x=>({...x,language:'java'}))];try{const r=await api();if(r.ok){account=r.value.account;state=r.value.state;}else if(r.status===401)signedOut=true;else loadError='Cloud progress could not load. The figures below do not represent your saved account until you reconnect.';}catch{loadError='Cloud progress could not load. The figures below do not represent your saved account until you reconnect.';}render();}catch{$('hub-content').innerHTML='<div class="notice error">The course could not load. Refresh to try again.</div>';}}addEventListener('beforeunload',e=>{if(profileDirty){e.preventDefault();e.returnValue='';}});start();
})();
